#include <bits/stdc++.h>
using namespace std;
// DP over X-runs: each Y can eat one whole adjacent X-run; there are (#Y) eaters and (#runs) runs
int main(){ string s; cin>>s; vector<long long> runs; long long cur=0; int ys=0;
  for(char ch:s){ if(ch=='X') cur++; else { runs.push_back(cur); cur=0; ys++; } } runs.push_back(cur);
  long long total=0; for(auto r:runs) total+=r;
  if(ys==0){ cout<<0<<"\n"; return 0; }
  // runs.size() == ys+1; Ys can cover any ys of the ys+1 runs, so we drop the smallest one
  long long mn=*min_element(runs.begin(),runs.end()); cout<<total-mn<<"\n"; }
